using System.ComponentModel;
using System.Diagnostics;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
namespace FontFilter;
public sealed record FontRow(string Title,string Subtitle,string Tags,List<FontRecord> Fonts);
public partial class MainWindow:Window
{
 readonly FontStore store;readonly UserSettings settings;readonly FontScanner scanner=new();readonly List<FontRecord> comparison=new();
 readonly DispatcherTimer searchTimer=new(){Interval=TimeSpan.FromMilliseconds(180)};readonly DispatcherTimer previewTimer=new(){Interval=TimeSpan.FromMilliseconds(180)};
 CancellationTokenSource? scanCts;Task? scanTask;FontRecord? current;List<FontRecord> matches=new();int queryVersion;bool ready,closing,closed,changingSample,favoritesOnly;
 public MainWindow(){InitializeComponent();store=new FontStore(Path.Combine(App.DataDirectory,"fonts.db"));settings=SettingsStore.Load();ThemeService.Apply(this,settings.ThemeColor);RenderQuickTags();settings.Api??=new();settings.Api.BaseUrl??="https://api.deepseek.com";settings.Api.Model??="";SizeSlider.Value=Math.Clamp(settings.Size,12,80);LineSlider.Value=Math.Clamp(settings.LineHeight,1,2.5);SampleText.Text=settings.Sample;UpdateSampleOptions();SampleBox.SelectedItem=((IEnumerable<string>)SampleBox.ItemsSource).Contains(settings.SampleMode)?settings.SampleMode:FontSamples.AutoKey;searchTimer.Tick+=async(_,_)=>{searchTimer.Stop();await RefreshAsync();};previewTimer.Tick+=(_,_)=>{previewTimer.Stop();RenderPreviews();};Loaded+=async(_,_)=>{StatusText.Text="正在更新标签词库…";await Task.Run(()=>{store.RefreshRuleTags();AttachCachedTags();});ready=true;RenderPreviews();await RefreshAsync();StatusText.Text=matches.Count==0?"尚无字体索引。点击“扫描 / 更新字体”开始；所有字体文件保持原样。":"索引已加载，可直接搜索。需要同步字体变动时再扫描。";};Closing+=OnClosing;}
 void AttachCachedTags(){var cache=Path.Combine(App.DataDirectory,"official-fonts.json");if(!File.Exists(cache))return;try{var catalogue=OfficialCatalogue.Load(cache);store.AttachOfficialTags(OfficialCatalogue.Match(store.All(),catalogue.Records));}catch(Exception ex){Dispatcher.Invoke(()=>StatusText.Text="官网缓存不可用："+ex.Message);}}
 async Task RefreshAsync(){if(closed)return;var version=++queryVersion;var q=QueryBox.Text;var onlyFavorites=favoritesOnly;try{var watch=Stopwatch.StartNew();var result=await Task.Run(()=>store.Search(q,onlyFavorites));if(closed||version!=queryVersion)return;matches=FontOrdering.Order(result).ToList();UpdateRows();CountText.Text=$"{result.Select(f=>f.Family).Distinct().Count()} 个家族 · {result.Count} 个字重 / 样式 · 查询 {watch.Elapsed.TotalMilliseconds:F0} ms";RenderQuickTags();}catch(Exception ex){if(!closed)StatusText.Text="读取索引失败："+ex.Message;}}
 void UpdateRows(){var selectedId=current?.Id;IEnumerable<FontRow> rows=GroupBox.IsChecked==true?matches.GroupBy(f=>f.Family).Select(g=>new FontRow((g.Any(f=>f.IsFavorite)?"★ ":"")+g.Key,$"{g.Count()} 个匹配字重 / 样式",string.Join(" ",g.SelectMany(f=>TagRules.Terms(f.ManualTags+" "+f.AutoTags)).Distinct().Take(12)),g.ToList())):matches.Select(f=>new FontRow((f.IsFavorite?"★ ":"")+f.Label,f.Vendor,f.Tags,new(){f}));FontList.ItemsSource=rows.ToList();if(selectedId!=null){var row=((IEnumerable<FontRow>)FontList.ItemsSource).FirstOrDefault(x=>x.Fonts.Any(f=>f.Id==selectedId));if(row!=null)FontList.SelectedItem=row;}if(FontList.SelectedItem==null&&FontList.Items.Count>0)FontList.SelectedIndex=0;if(FontList.Items.Count==0){current=null;FaceBox.ItemsSource=null;FamilyTitle.Text=favoritesOnly?"收藏中没有匹配字体":"没有匹配字体";AutoTagsText.Text="";ReasonText.Text=favoritesOnly?"先在全部字体中点击“☆ 收藏”，即可在这里查看。":"可减少关键词，或先补充介绍和人工标签。";PreviewPanel.Children.Clear();UpdateFavoriteButton();}}
 void Query_Changed(object sender,TextChangedEventArgs e){if(!ready)return;++queryVersion;searchTimer.Stop();searchTimer.Start();}
 void Grouping_Changed(object sender,RoutedEventArgs e){if(ready)UpdateRows();}
 void RenderQuickTags(){FavoritesFilterButton.Content=$"★ 收藏　{store.FavoriteCount}";FavoritesFilterButton.SetResourceReference(Control.BackgroundProperty,favoritesOnly?"AccentBrush":"SoftBrush");FavoritesFilterButton.SetResourceReference(Control.ForegroundProperty,favoritesOnly?"AccentTextBrush":"AccentInkBrush");QuickTagsPanel.Children.Clear();foreach(var tag in new[]{""}.Concat(settings.FrequentTags()).Concat(new[]{"黑体","宋体","隶书","书法","古籍","圆润"}).Distinct(StringComparer.OrdinalIgnoreCase).Take(13)){var button=new Button{Content=tag.Length==0?"全部":tag,Tag=tag,Style=(Style)FindResource("ChipButton")};if(!favoritesOnly&&((tag.Length==0&&string.IsNullOrWhiteSpace(QueryBox.Text))||(tag.Length>0&&TagRules.Terms(QueryBox.Text).Contains(tag)))){button.SetResourceReference(Control.BackgroundProperty,"AccentBrush");button.SetResourceReference(Control.ForegroundProperty,"AccentTextBrush");}button.Click+=Quick_Click;QuickTagsPanel.Children.Add(button);}}
 void RememberTags(IEnumerable<string> tags){settings.RecordTags(tags);SaveSettings();RenderQuickTags();}
 async void Quick_Click(object sender,RoutedEventArgs e){favoritesOnly=false;var tag=(string)((Button)sender).Tag;QueryBox.Text=tag;if(tag.Length>0)RememberTags(new[]{tag});searchTimer.Stop();await RefreshAsync();}
 async void FavoritesFilter_Click(object sender,RoutedEventArgs e){favoritesOnly=true;QueryBox.Clear();searchTimer.Stop();await RefreshAsync();}
 void UpdateFavoriteButton(){FavoriteButton.IsEnabled=current!=null;FavoriteButton.Content=current?.IsFavorite==true?"★ 已收藏":"☆ 收藏";}
 async void Favorite_Click(object sender,RoutedEventArgs e){if(current==null)return;var family=current.Family;var favorite=!current.IsFavorite;FavoriteButton.IsEnabled=false;try{await Task.Run(()=>store.SetFavorite(new[]{family},favorite));await RefreshAsync();StatusText.Text=favorite?"已收藏字体家族："+family:"已取消收藏："+family;}catch(Exception ex){StatusText.Text="收藏更新失败："+ex.Message;}finally{UpdateFavoriteButton();}}
 void ThemeSettings_Click(object sender,RoutedEventArgs e){var dialog=new ThemeSettingsWindow(settings.ThemeColor){Owner=this};if(dialog.ShowDialog()!=true)return;settings.ThemeColor=dialog.SelectedColor;ThemeService.Apply(this,settings.ThemeColor);SaveSettings();RenderQuickTags();StatusText.Text="主题颜色已保存。";}
 void Font_Selected(object sender,SelectionChangedEventArgs e){if(FontList.SelectedItem is not FontRow row)return;var previous=current?.Id;FaceBox.ItemsSource=row.Fonts;FaceBox.SelectedItem=row.Fonts.FirstOrDefault(f=>f.Id==previous)??row.Fonts.FirstOrDefault();}
 void Face_Changed(object sender,SelectionChangedEventArgs e){if(FaceBox.SelectedItem is not FontRecord font)return;current=font;UpdateFavoriteButton();ApplyAutoSample();FamilyTitle.Text=font.Family;TagsBox.Text=font.ManualTags;AutoTagsText.Text=font.AutoTags.Length>0?font.AutoTags:"暂无可确定的特征标签";SummaryText.Text=font.Summary.Length>0?font.Summary:"尚未补充字体介绍。可从官网提取，或录入你的观察。";SourceText.Text=$"{font.Vendor}  {font.Face}  |  {font.Source}";ReasonText.Text=QueryBox.Text.Trim().Length>0?TagRules.MatchReason(font,QueryBox.Text):font.Tags;SchedulePreview();}
 void SchedulePreview(){if(!ready)return;previewTimer.Stop();previewTimer.Start();}
 void Preview_Changed(object sender,RoutedPropertyChangedEventArgs<double> e)=>SchedulePreview();
 void SampleText_Changed(object sender,TextChangedEventArgs e){if(ready&&!changingSample)SampleBox.SelectedItem=FontSamples.FreeKey;SchedulePreview();}
 void RenderPreviews(){if(!ready||closed)return;PreviewPanel.Children.Clear();if(current!=null)PreviewPanel.Children.Add(new PreviewCard(current,SampleText.Text,SizeSlider.Value,LineSlider.Value));ComparePanel.Children.Clear();CompareTab.Header=$"上下对比（{comparison.Count}/6）";CompareEmpty.Visibility=comparison.Count==0?Visibility.Visible:Visibility.Collapsed;UpdateCompareTray();foreach(var f in comparison){var stack=new StackPanel{Margin=new Thickness(0,0,0,12)};var remove=new Button{Content="移除此字体",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,0,0,6)};remove.Click+=(_,_)=>{comparison.Remove(f);RenderPreviews();};stack.Children.Add(remove);stack.Children.Add(new PreviewCard(f,SampleText.Text,SizeSlider.Value,LineSlider.Value,true));ComparePanel.Children.Add(stack);}}
 void UpdateCompareTray(){CompareTray.Children.Clear();TrayCount.Text=$"{comparison.Count} / 6 款字体";TrayHint.Visibility=comparison.Count==0?Visibility.Visible:Visibility.Collapsed;foreach(var font in comparison){var chip=new Border{Background=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(237,243,237)),CornerRadius=new CornerRadius(7),Padding=new Thickness(10,8,10,8),Margin=new Thickness(0,0,6,0),MaxWidth=120,ToolTip=font.Label};chip.Child=new TextBlock{Text=font.Family,TextTrimming=TextTrimming.CharacterEllipsis,FontSize=10,Foreground=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(75,107,83))};CompareTray.Children.Add(chip);}}
 void UpdateSampleOptions()=>SampleBox.ItemsSource=new[]{FontSamples.AutoKey,FontSamples.FreeKey}.Concat(FontSamples.Defaults.Keys).Concat(settings.Samples.Keys).Distinct().ToList();
 void SetSampleText(string text){changingSample=true;try{SampleText.Text=text;}finally{changingSample=false;}SchedulePreview();}
 void ApplyAutoSample(){if(SampleBox.SelectedItem as string!=FontSamples.AutoKey||current==null)return;try{if(PreviewService.Resolve(current).TryGetGlyphTypeface(out var glyph)){var sample=FontSamples.Select(current,glyph.CharacterToGlyphMap);SetSampleText(sample.Value);SampleBox.ToolTip="自动适配："+sample.Key;}}catch{SampleBox.ToolTip="字体暂不可读取，请更新字体库。";}}
 void Sample_Changed(object sender,SelectionChangedEventArgs e){if(SampleBox.SelectedItem is not string key)return;if(key==FontSamples.AutoKey){ApplyAutoSample();return;}SampleBox.ToolTip=null;if(FontSamples.Defaults.TryGetValue(key,out var text)||settings.Samples.TryGetValue(key,out text))SetSampleText(text);}
 void SaveSample_Click(object sender,RoutedEventArgs e){var name=Prompt("保存预录段落","样文名称","自定义样文");if(string.IsNullOrWhiteSpace(name))return;settings.Samples[name.Trim()]=SampleText.Text;UpdateSampleOptions();SampleBox.SelectedItem=name.Trim();SaveSettings();StatusText.Text="样文已保存。";}
 void SaveSettings(){try{settings.Sample=SampleText.Text;settings.SampleMode=SampleBox.SelectedItem as string??FontSamples.AutoKey;settings.Size=SizeSlider.Value;settings.LineHeight=LineSlider.Value;SettingsStore.Save(settings);}catch(Exception ex){MessageBox.Show(this,"保存设置失败："+ex.Message);}}
 async void SaveTags_Click(object sender,RoutedEventArgs e){var rows=FontList.SelectedItems.Cast<FontRow>().ToArray();if(rows.Length==0)return;var ids=rows.SelectMany(x=>x.Fonts).Select(f=>f.Id).Distinct().ToArray();var tags=TagsBox.Text;try{await Task.Run(()=>store.SetManual(ids,tags));RememberTags(TagRules.Terms(tags));await RefreshAsync();StatusText.Text=$"已为{ids.Length}个字重 / 样式更新人工标签。";}catch(Exception ex){StatusText.Text="保存失败："+ex.Message;}}
 void AddCompare_Click(object sender,RoutedEventArgs e){if(current==null){StatusText.Text="请先在左栏选择字体。";return;}AddComparison(new[]{current});}
 void AddSelectedCompare_Click(object sender,RoutedEventArgs e){var fonts=FontList.SelectedItems.Cast<FontRow>().Select(row=>row.Fonts.FirstOrDefault(f=>f.Id==current?.Id)??row.Fonts.First()).ToArray();AddComparison(fonts);}
 void AddComparison(IEnumerable<FontRecord> fonts){int added=0,over=0;foreach(var font in fonts){if(comparison.Any(f=>f.Id==font.Id))continue;if(comparison.Count>=6){over++;continue;}comparison.Add(font);added++;}MainTabs.SelectedItem=CompareTab;RenderPreviews();StatusText.Text=over>0?$"已加入{added}款；对比上限6款，请先移除其他字体。":$"对比区 {comparison.Count}/6 款；左侧可Ctrl多选并批量加入。";}
 void FontList_DoubleClick(object sender,System.Windows.Input.MouseButtonEventArgs e){if(current!=null)AddComparison(new[]{current});}
 void TagLibrary_Click(object sender,RoutedEventArgs e){var definitions=store.AvailableTagDefinitions();var dialog=new TagPickerWindow(definitions,store.TagCounts(definitions.Select(t=>t.Name))){Owner=this};if(dialog.ShowDialog()!=true)return;RememberTags(dialog.SelectedTags);var existing=dialog.UseForSearch?QueryBox.Text:TagsBox.Text;var value=TagRules.SelectionText(existing,dialog.SelectedTags,dialog.UseForSearch);if(dialog.UseForSearch)QueryBox.Text=value;else{TagsBox.Text=value;StatusText.Text="标签已填入编辑框，点击“应用到选中结果”保存。";}}
 bool ApiReady(){try{return !string.IsNullOrWhiteSpace(settings.Api.Model)&&(!string.IsNullOrWhiteSpace(ApiSession.Key)||FontAiService.Endpoint(settings.Api.BaseUrl).IsLoopback);}catch(ArgumentException){return false;}}
 bool ConfigureApi(){var dialog=new ApiSettingsWindow(settings.Api,ApiSession.Key){Owner=this};if(dialog.ShowDialog()!=true)return false;settings.Api=dialog.Options;ApiSession.Key=dialog.ApiKey;SaveSettings();StatusText.Text="API配置已保存；密钥仅保留在本次运行中。";return true;}
 async void OfficialCatalogue_Click(object sender,RoutedEventArgs e){var dialog=new OfficialCatalogueWindow(store){Owner=this};if(dialog.ShowDialog()!=true)return;await RefreshAsync();var result=dialog.ImportResult;StatusText.Text=result==null?"资料库已关闭。":$"已补充{result.Added}个样式的官方介绍；已有资料{result.Existing}个，未覆盖。";}
 void ApiSettings_Click(object sender,RoutedEventArgs e)=>ConfigureApi();
 async void AiAnalyze_Click(object sender,RoutedEventArgs e){if(current==null){StatusText.Text="请先选择字体。";return;}if(!ApiReady()){if(!ConfigureApi())return;}var target=current;var dialog=new AiAnalysisWindow(target,settings.Api,ApiSession.Key){Owner=this};if(dialog.ShowDialog()!=true)return;try{await SaveAiTagsAsync(target,dialog.SelectedTags);StatusText.Text="已保存人工确认的AI标签，原有标签已保留。";}catch(Exception ex){StatusText.Text="标签保存失败："+ex.Message;}}
 async Task SaveAiTagsAsync(FontRecord target,IEnumerable<string> selected){var tags=string.Join(" ",TagRules.Terms(current?.Id==target.Id?TagsBox.Text:target.ManualTags).Concat(selected).Distinct(StringComparer.OrdinalIgnoreCase));await Task.Run(()=>store.SetManual(new[]{target.Id},tags));await RefreshAsync();}
 void MainTabs_SelectionChanged(object sender,SelectionChangedEventArgs e){if(!ReferenceEquals(e.Source,MainTabs)||ArchivePanel==null||WorkspaceGrid==null)return;var comparing=MainTabs.SelectedItem==CompareTab;ArchivePanel.Visibility=comparing?Visibility.Collapsed:Visibility.Visible;Grid.SetColumnSpan(WorkspaceGrid,comparing?3:1);}
 void OpenCompare_Click(object sender,RoutedEventArgs e){MainTabs.SelectedItem=CompareTab;RenderPreviews();}
 void ClearCompare_Click(object sender,RoutedEventArgs e){comparison.Clear();RenderPreviews();}
 async void Scan_Click(object sender,RoutedEventArgs e){if(scanTask!=null)return;scanCts=new();ScanButton.IsEnabled=false;PauseButton.IsEnabled=CancelButton.IsEnabled=true;scanner.Resume();PauseButton.Content="暂停";StatusText.Text="正在枚举系统字体，首次扫描可能需要一段时间…";var progress=new Progress<ScanProgress>(p=>{if(closed)return;ScanProgressBar.Value=p.Total==0?0:p.Done*100.0/p.Total;StatusText.Text=$"扫描 {p.Done}/{p.Total} 家族 · {p.Name} · 复用 {p.Reused} · 跳过异常 {p.Errors}";});scanTask=ScanCoreAsync(progress,scanCts.Token);await scanTask;scanTask=null;scanCts.Dispose();scanCts=null;ScanButton.IsEnabled=true;PauseButton.IsEnabled=CancelButton.IsEnabled=false;PauseButton.Content="暂停";}
 async Task ScanCoreAsync(IProgress<ScanProgress> progress,CancellationToken ct){try{var watch=Stopwatch.StartNew();var result=await scanner.ScanAsync(store,progress,ct);await Task.Run(AttachCachedTags);await RefreshAsync();StatusText.Text=$"{(result.Complete?"扫描完成":"已取消，保留已扫描结果")}：{result.Faces} 个样式 · 复用 {result.Reused} · 异常 {result.Errors} · {watch.Elapsed.TotalSeconds:F1} 秒";}catch(OperationCanceledException){StatusText.Text="扫描已取消。";}catch(Exception ex){StatusText.Text="扫描失败："+ex.Message;}}
 void Pause_Click(object sender,RoutedEventArgs e){scanner.TogglePause();PauseButton.Content=scanner.IsPaused?"继续":"暂停";}
 void Cancel_Click(object sender,RoutedEventArgs e){scanCts?.Cancel();scanner.Resume();}
 async void Metadata_Click(object sender,RoutedEventArgs e){if(current==null)return;var target=current;var dialog=new MetadataWindow(target){Owner=this};if(dialog.ShowDialog()==true){try{await dialog.SaveToAsync(store,target.Id);await RefreshAsync();StatusText.Text="介绍已保存，规则标签已更新；人工标签保持。";}catch(Exception ex){StatusText.Text="保存介绍失败："+ex.Message;}}}
 void FindOfficial_Click(object sender,RoutedEventArgs e){if(current==null)return;var q="(site:foundertype.com OR site:hanyi.com.cn OR site:hanyi.com) "+current.Family+" 字体介绍";try{Process.Start(new ProcessStartInfo("https://www.bing.com/search?q="+Uri.EscapeDataString(q)){UseShellExecute=true});}catch(Exception ex){StatusText.Text="打开浏览器失败："+ex.Message;}}
 void ShowMetadata_Click(object sender,RoutedEventArgs e){if(current==null)return;MessageBox.Show(this,(current.Summary.Length>0?current.Summary:"尚未收录介绍。可粘贴官方介绍，或从官方详情页提取。")+"\n\n来源："+current.Url+"\n更新时间："+current.Updated+"\n\n规则推断："+current.AutoTags+"\n人工标注："+current.ManualTags,current.Label);}
 static string? Prompt(string title,string label,string initial){var box=new TextBox{Text=initial,Margin=new Thickness(0,10,0,16)};var save=new Button{Content="保存",IsDefault=true,HorizontalAlignment=HorizontalAlignment.Right};var panel=new StackPanel{Margin=new Thickness(22)};panel.Children.Add(new TextBlock{Text=label});panel.Children.Add(box);panel.Children.Add(save);var window=new Window{Title=title,Content=panel,Width=380,Height=200,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=Application.Current.MainWindow,ResizeMode=ResizeMode.NoResize};save.Click+=(_,_)=>window.DialogResult=true;return window.ShowDialog()==true?box.Text:null;}
 async void OnClosing(object? sender,CancelEventArgs e){if(closed)return;if(closing){e.Cancel=true;return;}e.Cancel=true;closing=true;await Dispatcher.Yield(DispatcherPriority.Background);scanCts?.Cancel();scanner.Resume();if(scanTask!=null)await scanTask;searchTimer.Stop();previewTimer.Stop();++queryVersion;SaveSettings();closed=true;scanner.Dispose();store.Dispose();Close();}
}
